	/**
	 * Default Constructor
	 */
    public OperationService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new OperationEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(OperationRepository.class) );
		this.validator		= applicationContext.getBean(OperationValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Operation
	 */
		public Operation createOperation( CreateOperationCommand command ) {

		Operation entity = new Operation();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setOperationId( command.getOperationId() );
            entity.setOperationNumber( command.getOperationNumber() );
            entity.setName( command.getName() );
            entity.setSetupTime( command.getSetupTime() );
            entity.setStandardCycleTime( command.getStandardCycleTime() );
            entity.setOperationType( command.getOperationType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Operation {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateOperationCommand
	 * @return		Operation
	 */
	public Operation updateOperation( UpdateOperationCommand command ) {

		Operation entity = new Operation();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setOperationId( command.getOperationId() );
            entity.setOperationNumber( command.getOperationNumber() );
            entity.setName( command.getName() );
            entity.setSetupTime( command.getSetupTime() );
            entity.setStandardCycleTime( command.getStandardCycleTime() );
            entity.setRouting( command.getRouting() );
            entity.setWorkCenter( command.getWorkCenter() );
            entity.setInspectionPlan( command.getInspectionPlan() );
            entity.setOperationType( command.getOperationType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Operation {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteOperationCommand
	 */
	public void delete( DeleteOperationCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getOperationId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Operation {0} ", id );

	}

	/**
	 * Method to retrieve the Operation via OperationFetchOneSummary
	 * @param 	summary OperationFetchOneSummary
	 * @return 	OperationFetchOneResponse
	 */
	public Operation getOperation( OperationFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "OperationFetchOneSummary arg cannot be null" );

		Operation entity = null;
		UUID id = summary.getOperationId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Operation using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Operations
	 *
	 * @return 	List<Operation>
	 */
    public List<Operation> getAllOperation() {
		List<Operation> list = projector.findAll( new FindAllOperationQuery() );
		return list;
	}

	/**
	 * assign Routing on Operation
	 * @param		command AssignRoutingToOperationCommand
	 */
	public void assignRouting( AssignRoutingToOperationCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignRouting(command.getOperationId(), command.getAssignment());

	}

	/**
	 * unAssign Routing on Operation
	 * @param		command UnAssignRoutingFromOperationCommand
	 */
	public void unAssignRouting( UnAssignRoutingFromOperationCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignRouting(command.getOperationId());
	}
	
